<?php
 declare(strict_types=1);
 require_once __DIR__.'/../includes/admission_service.php';
 require_once __DIR__.'/../includes/workflow_layout.php';
 require_permission('admission.manage');$pdo=db();
 $periods=$pdo->query('SELECT id,name,status FROM admission_periods ORDER BY id DESC')->fetchAll();$periodId=(int)($_POST['period_id'] ?? $_GET['period_id'] ?? ($periods[0]['id'] ?? 0));
 $cfg=period_configuration($pdo,$periodId);$error='';
 if($_SERVER['REQUEST_METHOD']==='POST'){
     require_csrf();try{
         $actor=(int)auth_user()['user_id'];$action=(string)($_POST['action'] ?? 'calculate');$runId=(int)($_POST['run_id'] ?? 0);
         if($action==='calculate'){
             $_SESSION['selection_preview'][$periodId]=selection_preview($pdo,$periodId,$actor)+['actor'=>$actor,'token'=>bin2hex(random_bytes(24))];
             header('Location: '.url('/admission/calculate.php?period_id='.$periodId.'&preview=1'));exit;
         }
         elseif($action==='cancel'){unset($_SESSION['selection_preview'][$periodId]);header('Location: '.url('/admission/calculate.php?period_id='.$periodId));exit;}
         elseif($action==='confirm'){
             $preview=$_SESSION['selection_preview'][$periodId] ?? null;
             if(!$preview || $preview['actor']!==$actor || !hash_equals($preview['token'],(string)($_POST['preview_token'] ?? '')))throw new RuntimeException('Bản xem trước không hợp lệ. Hãy chạy lại.');
             selection_calculate($pdo,$periodId,$actor,$preview['report']['hash']);
             unset($_SESSION['selection_preview'][$periodId]);
         }
         elseif($action==='review')selection_review($pdo,$periodId,$runId,$actor);
         elseif($action==='tie')selection_tie_resolve($pdo,$periodId,$runId,(string)($_POST['tie_key'] ?? ''),(array)($_POST['chosen'] ?? []),(string)($_POST['evidence'] ?? ''),$actor);
         elseif($action==='bonus')selection_bonus_save($pdo,$periodId,(int)($_POST['candidate_id'] ?? 0),(string)($_POST['priority_group'] ?? ''),(string)($_POST['award_group'] ?? ''),(string)($_POST['evidence'] ?? ''),$actor);
         else throw new InvalidArgumentException('Thao tác không hợp lệ.');
         header('Location: '.url('/admission/calculate.php?period_id='.$periodId.'&saved=1'));exit;
     }catch(Throwable $e){$error=$e instanceof PDOException?'Không thể lưu dữ liệu. Vui lòng tải lại và kiểm tra dữ liệu liên quan.':$e->getMessage();if($e instanceof PDOException)error_log($e->getMessage());}
 }
 $run=latest_admission_run($pdo,$periodId);$snap=$run && selection_schema($pdo)?selection_snapshot($pdo,(int)$run['id']):null;$report=$snap['report'] ?? null;
 $prerequisites=admission_check_prerequisites($pdo,$periodId);$rows=$run?admission_results($pdo,(int)$run['id']):[];$pageCount=max(1,(int)ceil(count($rows)/50));$page=min($pageCount,max(1,(int)($_GET['page'] ?? 1)));
 $preview=isset($_GET['preview'])?($_SESSION['selection_preview'][$periodId] ?? null):null;
 $published=admission_results_published($pdo,$periodId);workflow_layout_start('Xét tuyển và duyệt kết quả','admission');
 ?>
 <h1 class="h3">Xét tuyển và duyệt kết quả · TP.HCM</h1>
 <form method="get" class="mb-3"><label class="form-label w-100">Kỳ tuyển sinh<select class="form-select" name="period_id" onchange="this.form.submit()"><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=$p['id']==$periodId?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><noscript><button>Xem</button></noscript></form>
 <?php if($cfg && $cfg['settings']['mode']==='simulation'):?><div class="alert alert-warning">MÔ PHỎNG — Kết quả chỉ phục vụ dự án.</div><?php endif;?>
 <?php if($error):?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Đã lưu thao tác. Kiểm tra trạng thái lượt xét tuyển bên dưới.</div><?php endif;?>
 <p class="d-flex flex-wrap gap-2"><a class="btn btn-outline-primary" href="<?=e(url('/admission/manage.php?id='.$periodId))?>">Kế hoạch</a><a class="btn btn-outline-primary" href="<?=e(url('/exam/grading.php?period_id='.$periodId))?>">Điểm thi và phúc khảo</a><a class="btn btn-outline-secondary" href="<?=e(url('/publication/index.php?period_id='.$periodId))?>">Công bố kết quả</a></p>
 <div class="card p-3 mb-3"><h2 class="h5">1. Điều kiện chạy xét tuyển</h2><p>Mô hình mô phỏng dùng chỉ tiêu chung của mỗi trường qua NV1 → NV2 → NV3. Mỗi học sinh trúng tuyển tối đa một nguyện vọng. Điểm sau phúc khảo và mức xử phạt của bài được đưa vào tính; điểm cộng cần minh chứng đã đối chiếu.</p><p>Vắng thi, điểm 0 hoặc hồ sơ không đủ điều kiện được ghi rõ trong báo cáo, không làm ngừng toàn bộ kỳ. Thiếu điểm hoặc dữ liệu không hợp lệ bị loại và ghi cảnh báo. Đồng tổng điểm xét tuyển thì ưu tiên tổng điểm gốc ba môn hệ số 1 cao hơn, không gồm điểm cộng. Nếu vẫn bằng nhau tại ranh giới chỉ tiêu thì chặn lưu.</p>
 <?php if($prerequisites):?><ul><?php foreach($prerequisites as $issue):?><li><?=e($issue)?></li><?php endforeach;?></ul><?php else:?><p class="text-success">Đã đủ điều kiện kiểm tra dữ liệu và chạy mô phỏng.</p><?php endif;?>
 <form method="post"><?=csrf_field()?><input type="hidden" name="period_id" value="<?=$periodId?>"><button class="btn btn-primary" name="action" value="calculate" <?=$prerequisites || $published || ($run && in_array($run['status'],['calculated','finalized'],true))?'disabled':''?>>Chạy xét tuyển mô phỏng</button></form></div>
 <?php if($cfg && selection_schema($pdo)): $students=$pdo->prepare('SELECT DISTINCT c.id,c.full_name,n.exam_number FROM candidates c JOIN aspirations a ON a.candidate_id=c.id LEFT JOIN exam_candidate_numbers n ON n.candidate_id=c.id AND n.admission_period_id=a.admission_period_id WHERE a.admission_period_id=? ORDER BY c.full_name,c.id');$students->execute([$periodId]);$students=$students->fetchAll();$policy=admission_policy();?>
 <details class="card p-3 mb-3"><summary>2. Đối chiếu điểm ưu tiên và khuyến khích</summary><p>Không tự cộng nhiều mức trong cùng nhóm. Chỉ nhập nhóm có mức cao nhất đã đối chiếu. Tổng điểm cộng tối đa 3,5. Thay đổi sau khi chạy sẽ làm lượt cũ cần chạy lại.</p>
 <form method="post"><?=csrf_field()?><input type="hidden" name="period_id" value="<?=$periodId?>"><input type="hidden" name="action" value="bonus"><fieldset <?=$published?'disabled':''?> class="row g-2"><div class="col-md-4"><label class="form-label w-100">Học sinh<select class="form-select" name="candidate_id" required><option value="">Chọn học sinh</option><?php foreach($students as $c):?><option value="<?=$c['id']?>"><?=e(($c['exam_number'] ?? '').' · '.$c['full_name'])?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label class="form-label w-100">Nhóm ưu tiên<select class="form-select" name="priority_group"><?php foreach($policy['priority_groups'] as $key=>$value):?><option value="<?=e($key)?>"><?=e(['none'=>'Không có','group_1'=>'Nhóm 1','group_2'=>'Nhóm 2','group_3'=>'Nhóm 3'][$key].' · '.$value.' điểm')?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label class="form-label w-100">Khuyến khích<select class="form-select" name="award_group"><?php foreach($policy['encouragement_awards'] as $key=>$value):?><option value="<?=e($key)?>"><?=e(['none'=>'Không có','gold_first'=>'Vàng / Nhất','silver_second'=>'Bạc / Nhì','bronze_third'=>'Đồng / Ba'][$key].' · '.$value.' điểm')?></option><?php endforeach;?></select></label></div><label class="form-label">Minh chứng / biên bản đối chiếu<textarea class="form-control" name="evidence" minlength="10" maxlength="4000" required></textarea></label><div><button class="btn btn-outline-primary">Lưu đối chiếu điểm cộng</button></div></fieldset></form></details><?php endif;?>
 <?php if($run):?><div class="card p-3 mb-3"><h2 class="h5">3. Lượt xét tuyển #<?=(int)$run['id']?> · <?=e(['blocked'=>'Cần rà soát đồng điểm','calculated'=>'Đã xét tuyển, chờ duyệt','finalized'=>'Đã công bố','draft'=>'Nháp'][$run['status']])?></h2>
 <?php if($snap):?><p class="small text-muted">Dữ liệu đầu vào và báo cáo được lưu riêng theo lượt; duyệt và công bố sẽ đối chiếu lại với dữ liệu hiện tại.</p><?php endif;?>
 <?php if($report && !$report['tie']):?><p><?=count($report['candidates'])?> học sinh · <?=count($report['assigned'])?> trúng tuyển · <?=count(array_filter($report['candidates'],static fn($c)=>!$c['eligible_selection']))?> hồ sơ không đủ điều kiện.</p>
 <div class="table-responsive"><table class="table"><thead><tr><th>Trường</th><th>Chỉ tiêu</th><th>Trúng tuyển</th><th>Còn chỗ</th><th>Ngưỡng mô phỏng NV1 / NV2 / NV3</th></tr></thead><tbody><?php foreach($snap['inputs']['quotas'] as $q):$school=(int)$q['school_id'];?><tr><td><?=e($q['name'])?></td><td><?=(int)$q['quota']?></td><td><?=$report['used'][$school] ?? 0?></td><td><?=max(0,(int)$q['quota']-(int)($report['used'][$school] ?? 0))?></td><td><?=e(implode(' / ',array_map(static fn($p)=>(string)($report['cutoffs'][$school]['NV'.$p] ?? '—'),[1,2,3])))?></td></tr><?php endforeach;?></tbody></table></div>
 <form method="post"><?=csrf_field()?><input type="hidden" name="period_id" value="<?=$periodId?>"><input type="hidden" name="run_id" value="<?=$run['id']?>"><button class="btn btn-success" name="action" value="review" <?=$published?'disabled':''?>>Duyệt lượt xét tuyển hiện tại</button> <?php if($snap['reviewed_at']):?><span class="small">Đã duyệt lúc <?=e($snap['reviewed_at'])?></span><?php endif;?></form>
 <p class="mt-3 mb-0"><a href="<?=e(url('/admission/export.php?run_id='.$run['id']))?>">Xuất toàn bộ kết quả CSV</a></p>
 <?php elseif(!empty($report['tie'])):$tie=$report['tie'];?><div class="alert alert-warning">Đồng điểm <?=e((string)$tie['score'])?> · <?=e($tie['school_name'])?> · NV<?=(int)$tie['priority']?>. Có <?=count($tie['candidates'])?> học sinh cho <?=(int)$tie['seats']?> chỗ còn lại trong nhóm. Lượt này chưa ghi danh sách trúng tuyển.</div>
 <form method="post"><?=csrf_field()?><input type="hidden" name="period_id" value="<?=$periodId?>"><input type="hidden" name="run_id" value="<?=$run['id']?>"><input type="hidden" name="tie_key" value="<?=e($tie['key'])?>"><input type="hidden" name="action" value="tie"><label class="form-label w-100">Chọn đúng <?=(int)$tie['seats']?> học sinh theo biên bản mô phỏng<select class="form-select" multiple size="10" name="chosen[]" required><?php foreach($tie['candidates'] as $c):?><option value="<?=$c['id']?>"><?=e($c['exam_number'].' · '.$c['full_name'])?></option><?php endforeach;?></select></label><label class="form-label w-100">Biên bản / lý do quyết định mô phỏng<textarea class="form-control" name="evidence" minlength="10" maxlength="4000" required></textarea></label><button class="btn btn-outline-primary">Lưu biên bản mô phỏng</button><p class="small mt-2">Sau khi lưu, chạy lại xét tuyển để áp dụng. Đây không phải quy tắc phân xử đồng điểm chính thức.</p></form>
 <?php endif;?></div><?php endif;?>
 <?php if($rows):?><h2 class="h5">Kết quả theo từng nguyện vọng</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Học sinh</th><th>NV</th><th>Trường</th><th>Điểm thi</th><th>Điểm cộng</th><th>Điểm xét tuyển</th><th>Kết quả / lý do</th></tr></thead><tbody><?php foreach(array_slice($rows,($page-1)*50,50) as $r):$c=$report['candidates'][(int)$r['candidate_id']] ?? null;?><tr><td><?=e($r['full_name'])?></td><td><?=(int)$r['priority_order']?></td><td><?=e($r['school_name'] ?? '')?></td><td><?=e((string)$r['score_total'])?></td><td><?=e((string)$r['priority_points'])?></td><td><?=e((string)$r['admission_score'])?></td><td><?=e($r['result_status']==='admitted'?'Trúng tuyển':($r['result_status']==='unprocessed'?implode(' ',$c['reasons'] ?? []):'Không trúng tuyển nguyện vọng này'))?></td></tr><?php endforeach;?></tbody></table></div><?php $pagePath='/admission/calculate.php';require __DIR__.'/../includes/list_pagination.php';endif;?>
 <?php require __DIR__.'/selection_preview.php'; ?>
 <?php workflow_layout_end();?>
